import { useCallback, useEffect, useId, useRef, useState } from 'react';
import { Button } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

type MenuDrawerProps = {
  onNavigate: (key: NavKey) => void;
  triggerLabel?: string;
};

const MAIN_ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function MenuDrawer({ onNavigate, triggerLabel = 'Меню' }: MenuDrawerProps) {
  const [open, setOpen] = useState(false);
  const panelId = useId();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const firstItemRef = useRef<HTMLButtonElement>(null);

  const close = useCallback(() => {
    setOpen(false);
    triggerRef.current?.focus();
  }, []);

  useEffect(() => {
    if (!open) return;
    firstItemRef.current?.focus();
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.stopPropagation();
        close();
      }
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [open, close]);

  const select = (key: NavKey) => {
    onNavigate(key);
    close();
  };

  return (
    <div className="jx-drawer-root">
      <Button
        ref={triggerRef}
        type="button"
        aria-expanded={open}
        aria-controls={panelId}
        onClick={() => setOpen((value) => !value)}
      >
        {triggerLabel}
      </Button>

      {open && (
        <div
          className="jx-overlay"
          onClick={close}
          style={{ position: 'fixed', inset: 0, zIndex: 'var(--jx-z-overlay, 40)' as never }}
        />
      )}

      <aside
        id={panelId}
        className="jx-panel jx-drawer jx-drawer--start"
        role="dialog"
        aria-modal="false"
        aria-label={triggerLabel}
        aria-hidden={!open}
        hidden={!open}
        style={{
          position: 'fixed',
          insetBlock: 0,
          insetInlineStart: 0,
          zIndex: 'var(--jx-z-drawer, 50)' as never,
          width: 'var(--jx-drawer-width, 280px)',
          padding: 'var(--jx-space-4, 16px)',
          borderRadius: 0,
          transform: open ? 'translateX(0)' : 'translateX(-100%)',
          transition: 'transform var(--jx-duration-md, 180ms) var(--jx-ease, ease)',
        }}
      >
        <nav className="jx-menu" aria-label={triggerLabel}>
          {MAIN_ITEMS.map((item, index) => (
            <button
              key={item.key}
              ref={index === 0 ? firstItemRef : undefined}
              type="button"
              className="jx-menu-item"
              onClick={() => select(item.key)}
            >
              {item.label}
            </button>
          ))}

          <hr className="jx-divider" aria-hidden="true" />

          <button
            type="button"
            className="jx-menu-item jx-menu-item--danger"
            data-variant="danger"
            onClick={() => select('logout')}
          >
            Выйти
          </button>
        </nav>
      </aside>
    </div>
  );
}

